import test from 'node:test';import assert from 'node:assert/strict';import {objects} from '../src/data.js';import {zones,hqBlocked} from '../src/zones.js';import {pathfind,cellAt,blocked} from '../src/navigation.js';import {getJournalEntries} from '../src/journal.js';
test('HQ room paths use doorways, avoid furniture, and reach every approach point',()=>{const points=[zones.hq.spawn,...objects.filter(o=>o.zone==='hq').map(o=>[o.x-65,o.y+55])];for(const a of points)for(const b of points){const p=pathfind(a,b,'hq');if(cellAt(...a).join()!==cellAt(...b).join())assert.ok(p.length,`${a} to ${b}`);for(const xy of p){const [x,y]=cellAt(...xy);assert.equal(blocked(x,y,'hq'),false);if(y===8)assert.ok([4,12,20].includes(x));}}assert.equal(hqBlocked(12,4),true);assert.deepEqual(pathfind(zones.hq.spawn,[500,180],'hq'),[])});
test('zones have reciprocal exits and valid spawns; inspection targets have content',()=>{for(const z of Object.values(zones)){assert.equal(blocked(...cellAt(...z.spawn),z.id),false);const gate=objects.find(o=>o.id===z.exit);assert.equal(gate.zone,z.id);assert.ok(zones[gate.to]);assert.ok(objects.some(o=>o.zone===gate.to&&o.kind==='portal'&&o.to===z.id))}assert.equal(new Set(objects.map(o=>o.id)).size,objects.length);for(const o of objects.filter(o=>o.kind==='inspect'))assert.ok(o.text&&o.diagram)});
test('HQ visits appear in journal and can be revisited by destination',()=>{for(const id of ['hq-map','hq-lab','hq-bunks','hq-pip']){const entries=getJournalEntries('adventures',new Set(),new Set([id]),objects,[]);assert.equal(entries.length,1);assert.equal(entries[0].target,id);assert.ok(entries[0].fact)}});
